1	import { ok, fail } from './result.js';
2	import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
3	import { getProduct } from './catalogue.js';
4	import { nextInvoiceNumber } from './numbering.js';
5	import { roundCents } from './money.js';
6	import { isValidDate, addDays } from './dates.js';
7	
8	/**
9	 * Create a draft invoice.
10	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} invoice
11	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
12	 */
13	export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
14	  // Normalize customer ID
15	  const normalizedCustomerId = normalizeId(customerId);
16	
17	  // Validate customer exists
18	  const customerResult = getCustomer(normalizedCustomerId);
19	  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');
20	
21	  // Validate issueDate is a real date in YYYY-MM-DD format
22	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
23	
24	  // Validate and calculate dueDate based on terms
25	  const validTerms = ['NET14', 'NET30', 'EOM'];
26	  if (!validTerms.includes(terms)) return fail('TERMS_INVALID');
27	
28	  let dueDate;
29	  if (terms === 'NET14') {
30	    dueDate = addDays(issueDate, 14);
31	  } else if (terms === 'NET30') {
32	    dueDate = addDays(issueDate, 30);
33	  } else if (terms === 'EOM') {
34	    const [yearStr, monthStr, dayStr] = issueDate.split('-');
35	    const year = parseInt(yearStr, 10);
36	    const month = parseInt(monthStr, 10);
37	    const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
38	    dueDate = `${yearStr}-${monthStr}-${String(lastDay).padStart(2, '0')}`;
39	  }
40	
41	  // Validate lines array is not empty
42	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
43	
44	  // Validate and build invoice lines
45	  const invoiceLines = [];
46	  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier] ?? 0;
47	
48	  for (const line of lines) {
49	    // Validate qty is a positive integer
50	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
51	
52	    // Determine discount: explicit discount wins, otherwise use tier discount
53	    const hasExplicitDiscount = Object.prototype.hasOwnProperty.call(line, 'discountPercent');
54	    const discountPercent = hasExplicitDiscount ? line.discountPercent : tierDiscount;
55	
56	    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
57	      return fail('DISCOUNT_INVALID');
58	    }
59	
60	    // Validate SKU exists and get product details
61	    const productResult = getProduct(line.sku);
62	    if (!productResult.ok) return fail('UNKNOWN_SKU');
63	
64	    const product = productResult.value;
65	    invoiceLines.push({
66	      sku: line.sku,
